:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #7f6ff0;
  --accent-pressed: #5a4bd1;
  --border: #3d3d5c;
  --radius: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.8rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: 0.5px;
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  line-height: 1.5;
  color: #b0b0c8;
}

.palette {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg);
  border-radius: var(--radius);
  padding: 12px;
  transition: transform 0.1s ease;
}

.swatch:hover {
  transform: scale(1.01);
}

.color-box {
  width: 64px;
  height: 64px;
  border-radius: 8px;
  flex-shrink: 0;
  border: 2px solid var(--border);
  transition: background 0.2s ease;
}

.swatch-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.hex-code {
  font-size: 1.1rem;
  font-weight: 600;
  font-family: 'Courier New', monospace;
  letter-spacing: 0.5px;
}

.lock-btn {
  background: var(--border);
  border: 2px solid transparent;
  border-radius: 8px;
  color: var(--text);
  font-size: 1.4rem;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  flex-shrink: 0;
}

.lock-btn:hover {
  background: var(--accent);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn.locked {
  background: var(--accent);
  border-color: #fff;
}

.lock-btn.locked:hover {
  background: var(--accent-hover);
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1.2rem;
  font-weight: 600;
  padding: 16px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  letter-spacing: 0.5px;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  .color-box {
    width: 48px;
    height: 48px;
  }
  .hex-code {
    font-size: 1rem;
  }
  .lock-btn {
    width: 40px;
    height: 40px;
    font-size: 1.2rem;
  }
}

const paletteEl = document.getElementById('palette');
const generateBtn = document.getElementById('generate');

const NUM_SWATCHES = 5;
let locked = new Array(NUM_SWATCHES).fill(false);
let currentColors = [];

// --- Color utilities ---
function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = n => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Generate a harmonious palette using a base hue and scheme
function generatePalette() {
  const baseHue = randomInt(0, 359);
  const schemes = [
    // analogous
    () => [0, 30, 60, 90, 120].map(offset => (baseHue + offset) % 360),
    // complementary
    () => [0, 180, 30, 210, 60].map(offset => (baseHue + offset) % 360),
    // triadic
    () => [0, 120, 240, 60, 180].map(offset => (baseHue + offset) % 360),
    // split complementary
    () => [0, 150, 210, 30, 180].map(offset => (baseHue + offset) % 360),
  ];
  const scheme = schemes[randomInt(0, schemes.length - 1)];
  const hues = scheme();
  const sat = randomInt(60, 85);
  const light = randomInt(45, 65);
  return hues.map(h => hslToHex(h, sat, light));
}

// --- Rendering ---
function render() {
  paletteEl.innerHTML = '';
  currentColors.forEach((hex, i) => {
    const swatch = document.createElement('div');
    swatch.className = 'swatch';

    const colorBox = document.createElement('div');
    colorBox.className = 'color-box';
    colorBox.style.backgroundColor = hex;

    const info = document.createElement('div');
    info.className = 'swatch-info';

    const hexLabel = document.createElement('span');
    hexLabel.className = 'hex-code';
    hexLabel.textContent = hex.toUpperCase();

    info.appendChild(hexLabel);

    const lockBtn = document.createElement('button');
    lockBtn.className = 'lock-btn' + (locked[i] ? ' locked' : '');
    lockBtn.setAttribute('aria-label', locked[i] ? `Unlock color ${hex}` : `Lock color ${hex}`);
    lockBtn.setAttribute('aria-pressed', locked[i]);
    lockBtn.textContent = locked[i] ? '🔒' : '🔓';
    lockBtn.addEventListener('click', () => toggleLock(i));

    swatch.appendChild(colorBox);
    swatch.appendChild(info);
    swatch.appendChild(lockBtn);
    paletteEl.appendChild(swatch);
  });
}

function toggleLock(index) {
  locked[index] = !locked[index];
  render();
}

function newPalette() {
  const fresh = generatePalette();
  currentColors = currentColors.length === 0
    ? fresh
    : fresh.map((hex, i) => (locked[i] ? currentColors[i] : hex));
  render();
}

// Initialize
currentColors = generatePalette();
render();
generateBtn.addEventListener('click', newPalette);
